// Go: worker pool với hàng đợi có giới hạn, từ chối khi đầy
jobs := make(chan Job, 200) // giới hạn = throughput x độ trễ chấp nhận

func handle(w http.ResponseWriter, r *http.Request) {
    select {
    case jobs <- newJob(r):
        w.WriteHeader(http.StatusAccepted)
    default: // hàng đợi đầy: báo quá tải thay vì giữ request
        w.Header().Set("Retry-After", "1")
        http.Error(w, "overloaded", http.StatusServiceUnavailable)
    }
}
